/// Batch controller class extends SysOperationServiceController
/// </summary>
public class METVendOpenItemsController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// Caption visible according to FSD 5046
    /// </summary>
    protected void new()
    {
        super();

        this.parmDialogCaption("@MET:VendOpenItemsActionMenuItem");
    }

/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// Automatically populates the batch text required by user before submitting to batch
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:VendOpenItemsBatchDesc";
}

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// Main method required to run the opration
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METVendOpenItemsController controller;

        controller = new METVendOpenItemsController();
        controller.initializeFromArgs(args);

        controller.startOperation();
        
    }

/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// BP to have a constructor for new controller.
/// </summary>
/// <returns>Controller instance</returns>
public static METVendOpenItemsController construct()
{
    return new METVendOpenItemsController();
}

    /// <summary>
    /// Validates the service parameters as per business validations.
    /// </summary>
    /// <returns>true/fale</returns>
    protected boolean validate()
    {
        boolean     ret = true;

        METVendOpenItemsContract    dataContract = this.getDataContractObject();

        if (!Global::isSystemAdministrator()
            && (dataContract.getVendLegalEntityId() == ''
            || dataContract.getVendAccountNum() == ''))
        {
            error("@MET:METPayNonSysAdminValidation");
            ret = false;
        }

        return ret;
    }
